from typing import List

def remove_spaces(paren_string: str) -> str:
    return paren_string.replace(" ", "")

def separate_paren_groups(paren_string: str) -> List[str]:
    def separate_group(group: str) -> str:
        stack = []
        result = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                stack.pop()
            if not stack:
                result.append(group[:len(result)*2+1])
        return result

    paren_string = remove_spaces(paren_string)
    groups = paren_string.split(')(')
    separated_groups = []
    for group in groups:
        separated_groups.extend(separate_group('(' + group + ')'))

    return separated_groups

